function validate([arr, k]) {
  const n = arr.length;
  if (n < 1 || n > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > n)) return 'Each value of arr is an integer from 1 to arr.length.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is an integer from 1 to arr.length.';
  return null;
}

