function kIncreasing(arr, k) {
  let operations = 0;
  for (let start = 0; start < k; start++) {
    const tails = [];
    let length = 0;
    for (let i = start; i < arr.length; i += k) {
      const value = arr[i];
      let left = 0;
      let right = tails.length;
      while (left < right) {
        const mid = (left + right) >> 1;
        if (tails[mid] <= value) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      tails[left] = value;
      length++;
    }
    operations += length - tails.length;
  }
  return operations;
}

