function kIncreasing(arr, k) {
  let total = 0;
  for (let r = 0; r < k; r++) {
    const chain = [];
    for (let i = r; i < arr.length; i += k) chain.push(arr[i]);
    const best = chain.map(() => 1);
    let keep = 0;
    for (let j = 0; j < chain.length; j++) {
      for (let p = 0; p < j; p++) if (chain[p] <= chain[j]) best[j] = Math.max(best[j], best[p] + 1);
      keep = Math.max(keep, best[j]);
    }
    total += chain.length - keep;
  }
  return total;
}

