function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 4);
  const top = mode === 0 ? Math.min(n, 3) : n;
  const arr = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  if (mode === 1) arr.sort((a, b) => b - a);
  if (mode === 2) arr.sort((a, b) => a - b);
  let k;
  if (size === 'large') {
    const choices = [1, 2, 3, 7, 50, n];
    k = Math.min(n, choices[Math.floor(rand() * choices.length)]);
  } else {
    k = 1 + Math.floor(rand() * n);
  }
  return [arr, k];
}
